WITH filtered AS (SELECT id, order_id, shipped_date, delivered_date, cost, status, DATE_FORMAT(delivered_date, 'yyyy-MM-dd') AS delivered_date_label, COALESCE(carrier, 'NONE') AS resolved_carrier FROM shipments WHERE shipped_date >= TO_DATE('2023-08-20') AND MONTH(delivered_date) IN (5, 9, 10)) SELECT status, order_id FROM filtered EXCEPT SELECT status, order_id FROM shipments WHERE order_id = 14;
